function updateGradientGuide(){const guide=$('#gradientGuide'),m=activeMask(),canvas=$('#canvas'),checker=$('#checker');if(!guide||!m||!['linear','radial'].includes(m.type)||!canvas?.getBoundingClientRect||!sourceImage.naturalWidth||$('#maskPanel')?.classList.contains('hidden')){guide?.classList.add('hidden');return}const a=E.sourcePointToOutput(sourceImage,current.edits,m.x,m.y),b=E.sourcePointToOutput(sourceImage,current.edits,m.x2,m.y2),rect=canvas.getBoundingClientRect(),host=checker.getBoundingClientRect(),ax=rect.left-host.left+a.x*rect.width,ay=rect.top-host.top+a.y*rect.height,bx=rect.left-host.left+b.x*rect.width,by=rect.top-host.top+b.y*rect.height,length=Math.hypot(bx-ax,by-ay),angle=Math.atan2(by-ay,bx-ax)*180/Math.PI,line=guide.querySelector('i'),start=guide.querySelector('.gradient-start'),end=guide.querySelector('.gradient-end'),ring=guide.querySelector('span');line.style.left=ax+'px';line.style.top=ay+'px';line.style.width=length+'px';line.style.transform='rotate('+angle+'deg)';start.style.left=ax+'px';start.style.top=ay+'px';end.style.left=bx+'px';end.style.top=by+'px';ring.classList.toggle('hidden',m.type!=='radial');if(m.type==='radial'){ring.style.left=ax-length+'px';ring.style.top=ay-length+'px';ring.style.width=ring.style.height=length*2+'px'}guide.classList.remove('hidden')}
