function resolvedPresetPatch(p){return{...p.patch,bw:p.group==='B&W'}}
function curveValue(points,x){const sorted=[...(points?.length?points:[[0,0],[255,255]])].sort((a,b)=>a[0]-b[0]);let index=0;while(index<sorted.length-2&&x>sorted[index+1][0])index++;const a=sorted[index],b=sorted[Math.min(index+1,sorted.length-1)],amount=b[0]===a[0]?0:(x-a[0])/(b[0]-a[0]);return a[1]+(b[1]-a[1])*amount}
