async function importPhotos(items){
  try{if(!items)items=await window.desktop.pickImages()}catch(error){reportFailure('Choose photos',error,'The photo picker could not be opened.');return}
  if(!items?.length)return;let firstNew=null,added=0,limited=0;const knownPaths=new Set(photos.map(photo=>photo.filePath.toLowerCase()));
  for(const f of items){if(photos.length>=MAX_CATALOG_PHOTOS){limited++;continue}const filePath=typeof f?.filePath==='string'?f.filePath:'';if(!filePath)continue;const pathKey=filePath.toLowerCase();if(knownPaths.has(pathKey))continue;knownPaths.add(pathKey);const p=E.migratePhoto({...f,filePath,id:uid(),importedAt:Date.now()+added});photos.push(p);firstNew??=p;added++}
  if(!added)return toast(limited?'The catalog photo limit has been reached':'Those photos are already in the catalog');catalogDirty=true;const saved=saveCatalog();updateLibrary();selectPhoto(firstNew);toast(saved?`${added} photo${added===1?'':'s'} imported${limited?` · ${limited} skipped at the catalog limit`:''}`:`${added} photo${added===1?'':'s'} available for this session, but the catalog is not saved · back up before closing`)
}
