  if(toolMode==='color'||toolMode==='point'){try{const px=Math.min(canvas.width-1,Math.floor(x*canvas.width)),py=Math.min(canvas.height-1,Math.floor(y*canvas.height)),context=canvas.getContext('2d');if(!context)throw new Error('Preview canvas is unavailable');const data=context.getImageData(px,py,1,1).data,[h]=E.rgbToHsl(data[0]/255,data[1]/255,data[2]/255);if(toolMode==='point')commit('Point color sample',()=>{current.edits.pointColor.enabled=true;current.edits.pointColor.hue=Math.round(h)});else{mixerColor=E.COLORS.reduce((best,name)=>{const distance=Math.abs((((h-E.HUE_CENTERS[name])+540)%360)-180);return distance<best[1]?[name,distance]:best},['red',999])[0];buildMixerSliders();toast(mixerColor+' color range selected')}switchRightPanel('edit');const colorPanel=$('[data-panel-name="Color Mixer"]');colorPanel.classList.remove('collapsed');colorPanel.scrollIntoView({behavior:'smooth'})}catch(error){reportFailure('Sample preview color',error,'That color could not be sampled from the preview.')}setTool('')}
